import {
  Api2
} from "./request-tracing-4nbah0zs.js";

// src/handlers/project.ts
import { Project } from "@opencode/core/project";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";
import { ProjectNotFoundError } from "@opencode/protocol/errors";
var ProjectHandler2 = HttpApiBuilder.group(Api2, "server.project", (handlers) => handlers.handle("project.list", (ctx) => Project.Service.use((project) => project.list(ctx.query))).handle("project.update", (ctx) => Project.Service.use((project) => project.update({ ...ctx.payload, projectID: ctx.params.projectID }).pipe(Effect.mapError(() => new ProjectNotFoundError({
  projectID: ctx.params.projectID,
  message: `Project not found: ${ctx.params.projectID}`
}))))));

export { ProjectHandler2 };
